"use strict";(self.webpackChunkhuman_behavior_site=self.webpackChunkhuman_behavior_site||[]).push([[1567],{5226:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"The Nature and Nurture of Cooperation","href":"/","docId":"index","unlisted":false},{"type":"category","label":"Learned Cooperation","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Roadmap","href":"/learned-cooperation/learned-cooperation-roadmap","docId":"learned-cooperation/learned-cooperation-roadmap","unlisted":false},{"type":"link","label":"Prisoner\'s Dilemma (One-Shot)","href":"/learned-cooperation/prisoners-dilemma","docId":"learned-cooperation/prisoners-dilemma","unlisted":false},{"type":"link","label":"Iterated Prisoner\'s Dilemma","href":"/learned-cooperation/iterated-prisoners-dilemma","docId":"learned-cooperation/iterated-prisoners-dilemma","unlisted":false},{"type":"link","label":"General Theory","href":"/learned-cooperation/theory","docId":"learned-cooperation/theory","unlisted":false},{"type":"category","label":"Repeated Prisonners Dilemma","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"MARL Bridge","href":"/learned-cooperation/repeated-prisonners-dilemma/overview","docId":"learned-cooperation/repeated-prisonners-dilemma/repeated-prisonners-dilemma-overview","unlisted":false}]}]},{"type":"category","label":"Selected Cooperation","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Theory","href":"/selected-cooperation/theory","docId":"selected-cooperation/theory","unlisted":false}]},{"type":"category","label":"Learning\u2013Selection Interaction","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Theory","href":"/learning-selection-interaction/theory","docId":"learning-selection-interaction/theory","unlisted":false}]},{"type":"category","label":"Archive","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Overview","href":"/archive/archive-overview","docId":"archive/archive-overview","unlisted":false},{"type":"category","label":"Human Behavior Patterns","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"The Human Behavior Patterns Project","href":"/archive/human-behavior-patterns/overview-hbp","docId":"archive/human-behavior-patterns/overview-hbp","unlisted":false},{"type":"category","label":"Fundamentals","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Fundamentals of Behavior","href":"/archive/human-behavior-patterns/fundamentals/overview-fundamentals","docId":"archive/human-behavior-patterns/fundamentals/overview-fundamentals","unlisted":false},{"type":"category","label":"Hierarchy","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Maslow\'s Pyramid","href":"/archive/human-behavior-patterns/fundamentals/hierarchy/maslow-hierarchy","docId":"archive/human-behavior-patterns/fundamentals/hierarchy/maslow-hierarchy","unlisted":false}]},{"type":"link","label":"Fundamentals per domain","href":"/archive/human-behavior-patterns/fundamentals/domains-fundamentals","docId":"archive/human-behavior-patterns/fundamentals/domains-fundamentals","unlisted":false}]},{"type":"category","label":"The Machinery","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"The Machinery","href":"/archive/human-behavior-patterns/machinery/overview-machinery","docId":"archive/human-behavior-patterns/machinery/overview-machinery","unlisted":false},{"type":"link","label":"The human reward system","href":"/archive/human-behavior-patterns/machinery/values-machinery","docId":"archive/human-behavior-patterns/machinery/values-machinery","unlisted":false}]},{"type":"category","label":"Predicting","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Humans as prediction machines","href":"/archive/human-behavior-patterns/predicting/overview-marl","docId":"archive/human-behavior-patterns/predicting/overview-marl","unlisted":false}]}]},{"type":"category","label":"Predator-Prey-Grass Project","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Predator-Prey-Grass Project","href":"/archive/pred-prey-grass/overview-ppg","docId":"archive/pred-prey-grass/overview-ppg","unlisted":false},{"type":"link","label":"Ecosystem","href":"/archive/pred-prey-grass/ecosystem/","docId":"archive/pred-prey-grass/ecosystem/ecosystem-ppg","unlisted":false},{"type":"category","label":"MARL","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Multi Agent Reinforcement Learning","href":"/archive/pred-prey-grass/marl/overview-marl","docId":"archive/pred-prey-grass/marl/overview-marl","unlisted":false}]},{"type":"category","label":"MARL used in PPG","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"MARL used in PredPreyGrass","href":"/archive/pred-prey-grass/marl-ppg/overview-marl-ppg","docId":"archive/pred-prey-grass/marl-ppg/overview-marl-ppg","unlisted":false},{"type":"category","label":"Challenges","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Challenges of Multi-Agent Reinforcement Learning (MARL) in Predator-Prey-Grass","href":"/archive/pred-prey-grass/marl-ppg/challenges/challenges-ppg","docId":"archive/pred-prey-grass/marl-ppg/challenges/challenges-ppg","unlisted":false},{"type":"category","label":"Rewards in PPG","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Rewards in PredPreyGrass MARL","href":"/archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/rewards","docId":"archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/rewards","unlisted":false},{"type":"link","label":"Rewards Scaling in PredPreyGrass MARL","href":"/archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/scaling","docId":"archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/scaling","unlisted":false}]},{"type":"link","label":"The Sequence in PredPreyGrass MARL","href":"/archive/pred-prey-grass/marl-ppg/challenges/sequence-ppg","docId":"archive/pred-prey-grass/marl-ppg/challenges/sequence-ppg","unlisted":false},{"type":"link","label":"The Solution Concept of PredPreyGrass MARL","href":"/archive/pred-prey-grass/marl-ppg/challenges/solution-concept-ppg","docId":"archive/pred-prey-grass/marl-ppg/challenges/solution-concept-ppg","unlisted":false}]},{"type":"category","label":"Hyper Parameter Tuning","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Hyper Parameter Tuning","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/tuning-ppg","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/tuning-ppg","unlisted":false},{"type":"link","label":"Tuning Conclusions","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/conclusions/","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/conclusions/tuning-conclusions-ppg","unlisted":false},{"type":"link","label":"Epochs Variation","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/epochs/","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/epochs/epochs-ppg","unlisted":false},{"type":"category","label":"Tuning Network","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Network Architecture","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/networks/network-architecture-ppg","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/networks/network-architecture-ppg","unlisted":false}]},{"type":"link","label":"Optuna with ASHA Pruning","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/optuna/","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/optuna/optuna-ppg","unlisted":false},{"type":"link","label":"Overview","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/pbt-overview","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/pbt-overview","unlisted":false},{"type":"category","label":"Population Based Training","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Configuration","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-config","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-config","unlisted":false},{"type":"link","label":"Implementation","href":"/archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-implementation","docId":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-implementation","unlisted":false}]}]},{"type":"category","label":"Experiments","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Red Queen","href":"/archive/pred-prey-grass/marl-ppg/experiments/red-queen/","docId":"archive/pred-prey-grass/marl-ppg/experiments/red-queen/red-queen-ppg","unlisted":false},{"type":"link","label":"Base Environment","href":"/archive/pred-prey-grass/marl-ppg/experiments/base-environment/","docId":"archive/pred-prey-grass/marl-ppg/experiments/base-environment/base-environment-ppg","unlisted":false},{"type":"link","label":"Mutating Agents","href":"/archive/pred-prey-grass/marl-ppg/experiments/mutating-agents/","docId":"archive/pred-prey-grass/marl-ppg/experiments/mutating-agents/mutating-agents-ppg","unlisted":false}],"href":"/archive/pred-prey-grass/marl-ppg/experiments/"}]},{"type":"link","label":"Related Research","href":"/archive/pred-prey-grass/related-research/","docId":"archive/pred-prey-grass/related-research/related-research-ppg","unlisted":false},{"type":"category","label":"Evolutionary Merits","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Implementing Behavioral Evolution Strategies in PredPreyGrass","href":"/archive/pred-prey-grass/evolutionary-merits-ppg/behavioral_strategies_codex_context","docId":"archive/pred-prey-grass/evolutionary-merits-ppg/behavioral_strategies_codex_context","unlisted":false},{"type":"link","label":"The Evolutionary Merits of PPG","href":"/archive/pred-prey-grass/evolutionary-merits-ppg/evolutionary-merits-ppg","docId":"archive/pred-prey-grass/evolutionary-merits-ppg/evolutionary-merits-ppg","unlisted":false},{"type":"link","label":"Ecology, Learning, and Evolution in PredPreyGrass","href":"/archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution","docId":"archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution","unlisted":false},{"type":"link","label":"Ecology, Learning, and Evolution in PredPreyGrass","href":"/archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution_clarified","docId":"archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution_clarified","unlisted":false}]},{"type":"link","label":"Malthusian Trap","href":"/archive/pred-prey-grass/malthusian-trap/","docId":"archive/pred-prey-grass/malthusian-trap/malthusian-trap-ppg","unlisted":false}]},{"type":"category","label":"Social Behavior","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Cooperation","href":"/archive/social-behavior/overview-cooperation","docId":"archive/social-behavior/overview-cooperation","unlisted":false},{"type":"category","label":"Altruism","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Altruism","href":"/archive/social-behavior/altruism/overview-altruism","docId":"archive/social-behavior/altruism/overview-altruism","unlisted":false}]},{"type":"link","label":"Why Do Humans Cooperate?","href":"/archive/social-behavior/why_humans_cooperate_abstract_reduction_and_marl_implications","docId":"archive/social-behavior/why_humans_cooperate_abstract_reduction_and_marl_implications","unlisted":false}]}]},{"type":"link","label":"To do","href":"/to_do","docId":"to_do","unlisted":false}]},"docs":{"archive/archive-overview":{"id":"archive/archive-overview","title":"Overview","description":"Use this section to park legacy, draft, or superseded pages without deleting them.","sidebar":"tutorialSidebar"},"archive/human-behavior-patterns/fundamentals/domains-fundamentals":{"id":"archive/human-behavior-patterns/fundamentals/domains-fundamentals","title":"Fundamentals per domain","description":"A closer look into the origins of behavior","sidebar":"tutorialSidebar"},"archive/human-behavior-patterns/fundamentals/hierarchy/maslow-hierarchy":{"id":"archive/human-behavior-patterns/fundamentals/hierarchy/maslow-hierarchy","title":"Maslow\'s Pyramid","description":"The Foundation: Physiological Needs and the PredPreyGrass Project","sidebar":"tutorialSidebar"},"archive/human-behavior-patterns/fundamentals/overview-fundamentals":{"id":"archive/human-behavior-patterns/fundamentals/overview-fundamentals","title":"Fundamentals of Behavior","description":"Which fundamentals do generate human behavior?","sidebar":"tutorialSidebar"},"archive/human-behavior-patterns/machinery/overview-machinery":{"id":"archive/human-behavior-patterns/machinery/overview-machinery","title":"The Machinery","description":"The Brain and Behavior \u2013 How does it work?","sidebar":"tutorialSidebar"},"archive/human-behavior-patterns/machinery/values-machinery":{"id":"archive/human-behavior-patterns/machinery/values-machinery","title":"The human reward system","description":"The human brain reward system is intricately linked to survival and reproduction, functioning to motivate behaviors that enhance both individual survival and the passing on of genes. Here\u2019s how survival and reproduction values are integrated into this system:","sidebar":"tutorialSidebar"},"archive/human-behavior-patterns/overview-hbp":{"id":"archive/human-behavior-patterns/overview-hbp","title":"The Human Behavior Patterns Project","description":"This project aims to model general human behavior patterns with Multi-Agent Reinforcemnent Learning (MARL). One of the most fascinating and controversial aspects of human behavior is cooperation. Therefore, this project in particular is focussed on how and under what minimal conditions multi-agent reinforcement-learning agents can learn cooperative behavior that is not explicitly rewarded, scripted, or evolutionarily inherited.","sidebar":"tutorialSidebar"},"archive/human-behavior-patterns/predicting/overview-marl":{"id":"archive/human-behavior-patterns/predicting/overview-marl","title":"Humans as prediction machines","description":"Human beings are essentially \u2018prediction machines\u2019. Human beings are always predicting something, consciously or subconsciously. Our brains are wired to constantly analyze patterns and make predictions based on those patterns in order to make sense of the world around us, to prepare for future events and to \u201cautocomplete\u2019 missing bits of information in our view of the world. In that perspective we make predictions for the short as well as for the long term. For acting as well as planning we use a mental model to navigate and guide us through an environment of threats as well as opportunities.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/ecosystem/ecosystem-ppg":{"id":"archive/pred-prey-grass/ecosystem/ecosystem-ppg","title":"The Predator, Prey, Grass Ecosystem","description":"This page explains how energy flows through the simulated ecosystem of grass, prey, and predators, and how entropy increases in accordance with the second law of thermodynamics. The diagram below visualizes the core concepts behind the simulation model.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/evolutionary-merits-ppg/behavioral_strategies_codex_context":{"id":"archive/pred-prey-grass/evolutionary-merits-ppg/behavioral_strategies_codex_context","title":"Implementing Behavioral Evolution Strategies in PredPreyGrass","description":"Cooperative vs Opportunistic Predator Policies (Codex Context File)","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/evolutionary-merits-ppg/evolutionary-merits-ppg":{"id":"archive/pred-prey-grass/evolutionary-merits-ppg/evolutionary-merits-ppg","title":"The Evolutionary Merits of PPG","description":"This document consolidates the discussion into a single, coherent reference.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution":{"id":"archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution","title":"Ecology, Learning, and Evolution in PredPreyGrass","description":"Morphological, Behavioral, and Life-History Perspectives","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution_clarified":{"id":"archive/pred-prey-grass/evolutionary-merits-ppg/predpreygrass_ecology_learning_evolution_clarified","title":"Ecology, Learning, and Evolution in PredPreyGrass","description":"Morphological, Behavioral, and Life-History Perspectives (Clarified)","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/malthusian-trap/malthusian-trap-ppg":{"id":"archive/pred-prey-grass/malthusian-trap/malthusian-trap-ppg","title":"The Malthusian Trap","description":"TODO","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/challenges/challenges-ppg":{"id":"archive/pred-prey-grass/marl-ppg/challenges/challenges-ppg","title":"Challenges of Multi-Agent Reinforcement Learning (MARL) in Predator-Prey-Grass","description":"Although a promissing tool, MARL faces many challenges. Also implementing the Predator-Prey-Grass (PPG) environment highlights many of the core challenges of MARL. Below, some are listed in general.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/rewards":{"id":"archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/rewards","title":"Rewards in PredPreyGrass MARL","description":"Rewards play a pivotal rol in reinforcement learning (RL). Although RL is seen as a fundamental different AI paradigm compared to supervised learning, rewards are essentially the supervised component in mainstream RL. Upfront, the designer needs to shape and therefore supervise the reward structure, inevitably leading to bias and subjectivity,","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/scaling":{"id":"archive/pred-prey-grass/marl-ppg/challenges/rewards-ppg/scaling","title":"Rewards Scaling in PredPreyGrass MARL","description":"One of the most subtle but crucial features in multi-agent reinforcement learning (MARL) is the reward magnitude \u2014 especially in environments where rewards are sparse and agents must coordinate to survive. In the custom-built MARL environment simulating predators, prey, and grass on a grid, changing the reproduction reward from 1.0 to 10.0 dramatically altered the course of learning. This section explains why that matters, and what it reveals about reward scaling in co-evolving agent populations.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/challenges/sequence-ppg":{"id":"archive/pred-prey-grass/marl-ppg/challenges/sequence-ppg","title":"The Sequence in PredPreyGrass MARL","description":"The sequence in Multi Agent Reinforcement Learning is of importance in simulation. Therefore, scheduling of the agents\u2019 activation is particularly important and the activation regime can have a substantial effect on the behavior of a simulation [Comer2014]. Most many-agent algorithms can in practice handle only instances where all learning agents step at the same time, because sequentially stepping makes it computationally very difficult to solve.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/challenges/solution-concept-ppg":{"id":"archive/pred-prey-grass/marl-ppg/challenges/solution-concept-ppg","title":"The Solution Concept of PredPreyGrass MARL","description":"MARL is not a singular problem solving concept. This already has been emphasized in  the landmark paper If multi-agent learning is the answer, what is the question?. (paper, 2007). In this paper five distinctive \\"agenda\'s\\" have been proposed to classify  most of the MARL related solutions concepts:","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/experiments/base-environment/base-environment-ppg":{"id":"archive/pred-prey-grass/marl-ppg/experiments/base-environment/base-environment-ppg","title":"Base Environment","description":"The base environment consists of two species: predator and prey. Both species are seperately trained, resulting into two separate policies.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/experiments/experiments-ppg":{"id":"archive/pred-prey-grass/marl-ppg/experiments/experiments-ppg","title":"Environment Experiments","description":"Environment experiments.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/experiments/mutating-agents/mutating-agents-ppg":{"id":"archive/pred-prey-grass/marl-ppg/experiments/mutating-agents/mutating-agents-ppg","title":"Mutating Agents Environment","description":"Additional features with respect to the base environment","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/experiments/red-queen/red-queen-ppg":{"id":"archive/pred-prey-grass/marl-ppg/experiments/red-queen/red-queen-ppg","title":"The Red Queen Effect","description":"\ud83e\uddec Introduction","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/conclusions/tuning-conclusions-ppg":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/conclusions/tuning-conclusions-ppg","title":"Conclusions Hyper Parameter Tuning","description":"We have extensively tried to tune the hyper parameters of the Predator-Prey-Grass PPO solution model.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/epochs/epochs-ppg":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/epochs/epochs-ppg","title":"Epochs Variation","description":"The number of epochs in the configuration has a strong impact on the wall time of iterations. The `numepochs` determines how many times PPO will re-use the same batch of collected experiences for gradient updates before sampling a new batch of fresh data. Essentially, the `numepochs` is a knob that trades off data efficiency vs. stability. Increasing  `num_epochs` increases stability of training but on the other hand takes more compute time.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/networks/network-architecture-ppg":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/networks/network-architecture-ppg","title":"Network Architecture","description":"\ud83c\udfde\ufe0f Short recap of the Environment","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/optuna/optuna-ppg":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/optuna/optuna-ppg","title":"Optuna with ASHA Pruning","description":"This experiment uses Optuna as the hyperparameter search algorithm, combined with ASHA (Asynchronous Successive Halving Algorithm) as the pruning scheduler. The setup allows us to explore a wide hyperparameter space, while quickly eliminating poorly performing trials to save compute.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/pbt-overview":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/pbt-overview","title":"Overview","description":"Population-Based Training (PBT) is a technique for efficiently searching and adapting hyperparameters during reinforcement learning.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-config":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-config","title":"Configuration","description":"Hyperparameter settings","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-implementation":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/population-based-training/pbt-implementation","title":"Implementation","description":"This experiment uses Population Based Training (PBT) to explore adaptive learning dynamics in a multi-agent Predator-Prey-Grass simulation. The goal is not to converge to a single optimal policy, but to allow diverse agent types to co-evolve and adapt their hyperparameters over time in response to a dynamic environment and each other.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/tuning-ppg":{"id":"archive/pred-prey-grass/marl-ppg/hyper-parameter-tuning/tuning-ppg","title":"Hyper Parameter Tuning","description":"In this section we provide experiments to tune the default solution of the default Predator-Prey-Grass environment towards a more efficient solution. Training a default environment satifactory (meaning that the simulation runs until truncation of 1000 evaluation steps), takes about 9 hours of compute time on a 32 CPU/1 GPU machine. The goal of our tuning experiments is to reduce compute time while remaining the same rewards (ie. reproduction) structure. The default PPO configuration is shown in Display 1.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl-ppg/overview-marl-ppg":{"id":"archive/pred-prey-grass/marl-ppg/overview-marl-ppg","title":"MARL used in PredPreyGrass","description":"The Predator, Prey, Grass project(PredPreyGrass) is implemented utilizing multi-agent reinforcement learning (MARL). The cusomized RLLb multi agent environment is trained using a Proximal Policy Optimization (PPO).","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/marl/overview-marl":{"id":"archive/pred-prey-grass/marl/overview-marl","title":"Multi Agent Reinforcement Learning","description":"Multi Agent Reinforcement Learning (MARL) as a tool for modeling human behavior","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/overview-ppg":{"id":"archive/pred-prey-grass/overview-ppg","title":"Predator-Prey-Grass Project","description":"The Predator-Prey-Grass project(PredPreyGrass) aims to investigate behavior of multiple agents in a simple closed grid world. Although only partially applicable to modern humans, this could shed light to ancestral human behavior. In the hunter-gatherer period of Homo Sapiens, until roughly 10,000 years ago a common setting, humans could be as well be predators as prey. Moreover, the limited availability of grass could be regarded as a proxy for the limited resources for humans down the food chain.","sidebar":"tutorialSidebar"},"archive/pred-prey-grass/related-research/related-research-ppg":{"id":"archive/pred-prey-grass/related-research/related-research-ppg","title":"Related Research","description":"Research at the intersection of multi-agent reinforcement learning (MARL), ecological modeling, and open-ended evolution spans several largely disconnected literatures. The present work builds on foundations in RL-based predator\u2013prey models, agent-based ecology, and artificial life, but differs substantially from existing approaches by integrating multi-trophic resource dynamics, energy-based metabolism, lineage-aware reproduction, and mutation-driven evolutionary variation within a unified MARL framework. Below, we summarize the most relevant work across these domains.","sidebar":"tutorialSidebar"},"archive/social-behavior/altruism/overview-altruism":{"id":"archive/social-behavior/altruism/overview-altruism","title":"Altruism","description":"Altruism is a form of social behavior where an individual incurs a cost to benefit another. It appears in biological systems (e.g., kin selection, reciprocal altruism) and in human societies through norms, institutions, and moral frameworks.","sidebar":"tutorialSidebar"},"archive/social-behavior/overview-cooperation":{"id":"archive/social-behavior/overview-cooperation","title":"Cooperation","description":"This section explores cooperation as a broad class of social behavior in natural and artificial systems.","sidebar":"tutorialSidebar"},"archive/social-behavior/why_humans_cooperate_abstract_reduction_and_marl_implications":{"id":"archive/social-behavior/why_humans_cooperate_abstract_reduction_and_marl_implications","title":"Why Do Humans Cooperate?","description":"A minimal, abstract synthesis \u2014 with implications for ecology, game theory, and multi\u2011agent reinforcement learning (MARL)","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"The Nature and Nurture of Cooperation","description":"How does cooperation emerge from learning and from evolution?","sidebar":"tutorialSidebar"},"learned-cooperation/iterated-prisoners-dilemma":{"id":"learned-cooperation/iterated-prisoners-dilemma","title":"Iterated Prisoner\'s Dilemma","description":"When the Prisoner\'s Dilemma is repeated, strategy is no longer a single move.","sidebar":"tutorialSidebar"},"learned-cooperation/learned-cooperation-roadmap":{"id":"learned-cooperation/learned-cooperation-roadmap","title":"Roadmap","description":"This section is organized around your central motto:","sidebar":"tutorialSidebar"},"learned-cooperation/prisoners-dilemma":{"id":"learned-cooperation/prisoners-dilemma","title":"Prisoner\'s Dilemma (One-Shot)","description":"The one-shot Prisoner\'s Dilemma captures the non-trivial core of cooperation.","sidebar":"tutorialSidebar"},"learned-cooperation/repeated-prisonners-dilemma/repeated-prisonners-dilemma-overview":{"id":"learned-cooperation/repeated-prisonners-dilemma/repeated-prisonners-dilemma-overview","title":"MARL Bridge","description":"This section summarizes the SequentialPrisonersDilemma project, where two independently trained PPO agents repeatedly play a Prisoner\'s Dilemma game. The goal is to test whether learned behavior converges to persistent defection, cooperative conventions, or mixed horizon-dependent patterns.","sidebar":"tutorialSidebar"},"learned-cooperation/theory":{"id":"learned-cooperation/theory","title":"General Theory","description":"Cooperation Within Lifetimes","sidebar":"tutorialSidebar"},"learning-selection-interaction/theory":{"id":"learning-selection-interaction/theory","title":"Theory","description":"A Two-Timescale Theory of Cooperation","sidebar":"tutorialSidebar"},"selected-cooperation/theory":{"id":"selected-cooperation/theory","title":"Theory","description":"Cooperation Across Generations","sidebar":"tutorialSidebar"},"to_do":{"id":"to_do","title":"To do","description":"on top of display 1 at overview","sidebar":"tutorialSidebar"}}}}')}}]);